create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin' check(role in ('admin','editor')), full_name text, created_at timestamptz default now());
create table if not exists public.transactions (id uuid primary key default gen_random_uuid(), transaction_date date not null default current_date, fund text not null check(fund in ('yatim','operasional','pembangunan','qurban')), type text not null check(type in ('in','out')), amount numeric(14,2) not null check(amount > 0), note text not null, evidence_url text, published boolean not null default false, voided_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.activities (id uuid primary key default gen_random_uuid(), title text not null, event_date date not null, description text, image_url text, published boolean default false, created_by uuid references auth.users(id), created_at timestamptz default now());
create table if not exists public.pages (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null check(slug ~ '^[a-z0-9-]+$'), content text not null, sort_order int default 0, published boolean default false, created_by uuid references auth.users(id), created_at timestamptz default now());
create table if not exists public.site_settings (key text primary key, value jsonb not null, updated_at timestamptz default now());
create table if not exists public.audit_logs (id bigint generated by default as identity primary key, user_id uuid, table_name text not null, record_id text, action text not null, old_data jsonb, new_data jsonb, created_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role in ('admin','editor')) $$;
alter table profiles enable row level security;alter table transactions enable row level security;alter table activities enable row level security;alter table pages enable row level security;alter table site_settings enable row level security;alter table audit_logs enable row level security;
create policy "public reads published transactions" on transactions for select using ((published=true and voided_at is null) or is_admin());
create policy "admin manages transactions" on transactions for all using (is_admin()) with check (is_admin());
create policy "public reads published activities" on activities for select using (published=true or is_admin());
create policy "admin manages activities" on activities for all using (is_admin()) with check (is_admin());
create policy "public reads published pages" on pages for select using (published=true or is_admin());
create policy "admin manages pages" on pages for all using (is_admin()) with check (is_admin());
create policy "public reads settings" on site_settings for select using (true);
create policy "admin manages settings" on site_settings for all using (is_admin()) with check (is_admin());
create policy "profile reads self" on profiles for select using (id=auth.uid());
create policy "admin reads logs" on audit_logs for select using (is_admin());
insert into activities(title,event_date,description,image_url,published) values ('Program Renovasi Masjid',current_date,'Mari bersama mewujudkan masjid yang nyaman dan indah untuk ibadah kita semua.','/banner-renovasi.jpg',true) on conflict do nothing;
